{
  "hypothesis": "Stocks that showed sustained directional drift in close prices over 30-60 days continue to outperform in the next period.",
  "factors": [
    {
      "name": "Momentum_Trend",
      "expression": "RANK(TS_ZSCORE(TS_PCTCHANGE($close, 30), 60))",
      "explanation": "Measures the relative strength of a stock's price trend over 30 days, standardized across the market over 60 days."
    },
    {
      "name": "Drift_Signal",
      "expression": "RANK(TS_MEAN($close, 30) - TS_MEAN($close, 60))",
      "explanation": "Compares the average closing price over two different time horizons to detect persistent directional movement."
    },
    {
      "name": "Volatility_Adjusted_Momentum",
      "expression": "RANK((TS_PCTCHANGE($close, 30) - TS_PCTCHANGE($close, 60)) / TS_STD($return, 60))",
      "explanation": "Standardizes momentum by dividing it by the volatility of returns over 60 days, capturing relative strength adjusted for risk."
    },
    {
      "name": "Ranking_Spread",
      "expression": "RANK(TS_QUANTILE($close, 60, 0.9) - TS_QUANTILE($close, 60, 0.1))",
      "explanation": "Measures the dispersion of closing prices over 60 days and ranks stocks based on this spread to identify strong trends."
    },
    {
      "name": "Decayline_Momentum",
      "expression": "RANK(DECAYLINEAR(TS_PCTCHANGE($close, 30), 20))",
      "explanation": "Applies a decaying weight to the 30-day return, emphasizing recent performance while fading older values."
    },
    {
      "name": "Cross_Term_Momentum",
      "expression": "RANK(TS_CORR($close, $volume, 30) * TS_PCTCHANGE($close, 60))",
      "explanation": "Combines price-volume correlation with long-term price momentum to detect stocks where volume amplifies directional movement."
    }
  ]
}

