  "factors": [
    {
      "name": "IntradayRangeSpikes",
      "expression": "RANK(TS_QUANTILE($high - $low, 20, 0.9) - TS_QUANTILE($high - $low, 20, 0.1))",
      "explanation": "Measures the gap between top and bottom 10% of intraday ranges over 20 days, aiming to capture extreme range expansions as a contrarian signal."
    },
    {
      "name": "RangeExpansionReversal",
      "expression": "RANK((TS_PCTCHANGE($high - $low, 5) - TS_PCTCHANGE($high - $low, 20)) * TS_ZSCORE($return, 5))",
      "explanation": "Combines short-term range growth with return volatility to detect reversal patterns following large intraday range expansions."
    },
    {
      "name": "RangeVolatilityContrast",
      "expression": "RANK((TS_STD($high - $low, 5) / TS_STD($high - $low, 20)) * (TS_MEAN($return, 5) - TS_MEAN($return, 20)))",
      "explanation": "Compares short-term and long-term range volatility with return trends to find stocks with extreme range expansions that underperform."
    },
    {
      "name": "HighLowDisparity",
      "expression": "RANK(TS_ARGMAX($high - $low, 5) - TS_ARGMIN($high - $low, 5))",
      "explanation": "Identifies stocks with the most volatile intraday ranges by finding the difference between the highest and lowest range days over 5 days."
    },
    {
      "name": "RangeSpikesWithReturn",
      "expression": "RANK((TS_QUANTILE($high - $low, 10, 0.9) - TS_QUANTILE($high - $low, 10, 0.1)) * TS_ZSCORE($return, 10))",
      "explanation": "Captures extreme intraday range expansions using quantiles and combines them with return volatility to identify potential reversals."
    }
  ]
}

