      "name": "RangeAsymmetry",
      "expression": "TS_ARGMAX($high, 5) - TS_ARGMIN($low, 5)",
      "explanation": "Identifies the extreme price points in a window, exploring the ORDER STATISTICS axis through argument max/min."
    },
    {
      "name": "DecayRangeSignal",
      "expression": "DECAYLINEAR(TS_PCTCHANGE($high - $low, 5), 10)",
      "explanation": "Applies decay to range changes, using the NEGLECTED OPERATOR axis to explore time-weighted signals."
    },
    {
      "name": "CrossVolatility",
      "expression": "TS_CORR($high - $low, $volume, 5) * TS_PCTCHANGE($return, 5)",
      "explanation": "Pairs range and volume correlation with return changes, testing the UNUSUAL PAIRING axis."
    },
    {
      "name": "ShapeReversal",
      "expression": "TS_KURT($high - $low, 5) - TS_SKEW($high - $low, 5)",
      "explanation": "Compares kurtosis and skewness of range expansions, exploring the SHAPE, NOT LEVEL axis."
    }
  ]
